import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";


const mimeTypes = {'.ico':'image/x-icon','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.gif':'image/gif','.svg':'image/svg+xml','.webp':'image/webp','.bmp':'image/bmp','.tiff':'image/tiff','.tif':'image/tiff','.avif':'image/avif','.heic':'image/heic','.jfif':'image/jpeg','.pjpeg':'image/jpeg','.pjp':'image/jpeg','.mp3':'audio/mpeg','.wav':'audio/wav','.ogg':'audio/ogg','.m4a':'audio/mp4','.mp4':'video/mp4','.webm':'video/webm','.ogv':'video/ogg','.mov':'video/quicktime','.css':'text/css','.js':'application/javascript','.mjs':'application/javascript','.woff':'font/woff','.woff2':'font/woff2','.ttf':'font/ttf','.otf':'font/otf','.eot':'application/vnd.ms-fontobject','.pdf':'application/pdf','.txt':'text/plain','.json':'application/json','.xml':'application/xml'};

const __dirname = path.dirname(fileURLToPath(import.meta.url));
//path.resolve(process.cwd(), relativePath);
const ojs = {
    get:(filePath,variable,extract=true)=>{
    let content = fs.readFileSync(path.resolve(process.cwd(),filePath)).toString();
    let requires = content.matchAll(/include\(["'](.*)["']\)/g);
    let requiresMatched = content.match(/include\(["'](.*)["']\)/g);
    let requiresExtract = [...requires];
    for(let r = 0; r < requiresExtract.length;  r++){
        let requiredFile,requiredFileLink = requiresExtract[r][1];
        try{
           requiredFile = fs.readFileSync(path.resolve(process.cwd(),requiredFileLink)).toString();
          content = content.replace(requiresMatched[r],requiredFile);
        }catch(e){
         throw e.message;
        }
    }
    if(extract == true){
    let allLinksBody = content.match(/<.*?(?:href|src)=["'](?!https?:|mailto:|tel:|#)(.*?)["'].*>/g);
    let allLinksLink = content.matchAll(/<.*?(?:href|src)=["'](?!https?:|mailto:|tel:|#)(.*?)["'].*>/g);
   allLinksLink = [...allLinksLink];
    for(let i = 0; i < allLinksLink.length;i++){
       
   let fileExt = path.extname(allLinksLink[i][1]);
   if(['.css','.js'].includes(fileExt)){
      try{
      let TagContent = fs.readFileSync(path.resolve(process.cwd(),allLinksLink[i][1])).toString();
      if(fileExt == ".css"){
           content = content.replace(allLinksBody[i],`<style>${TagContent}</style>`);
      }else{
           content = content.replace(allLinksBody[i],`<script>${TagContent}</script>`)
      }//  console.log(allLinksBody[i],);
      }catch(e){}
  //else if([".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg", ".ico", ".avif", ".bmp", ".tiff", ".heic"].includes(fileExt)){
    }else{
        try{
        let TagContent = fs.readFileSync(path.resolve(process.cwd(),allLinksLink[i][1])).toString('base64');
        let fileData = `data:${mimeTypes[fileExt.toLowerCase()]};base64,${TagContent}`;
        var category = mimeTypes[fileExt.toLowerCase()].split("/")[0];
        let regex;
        
          switch(category){
            case "video":
             regex = new RegExp(`src=["']${allLinksLink[i][1]}["']`);
        content = content.replace(regex,`src="${fileData}"`);
            break;
             default:
             regex = new RegExp(`href=["']${allLinksLink[i][1]}["']`);
        content = content.replace(regex,`href="${fileData}"`);
          }
        }catch(e){}
        
    }
    }
    }
    return olEng(content,variable);
    }
    

}

  const getIf = (content)=>{
    let i = 0;
    let result = [];
    let opening = null;
    let openCount = 0;
    let closingCount = 0;
    while(i < (content.length - 1)){
      let phrase = content[i]+content[i+1]+content[i+2]+content[i+3];
      if(phrase == "<if "){
      if(opening == null)opening = i;
      openCount++;
      // console.log(phrase)
      };
      if(phrase == "</if"){
        closingCount++;
      if(openCount == closingCount){
          result.push({start:opening,end:i+5});
          opening = null;
      }
        //console.log(phrase)
      };
    i++;
    }
    let allResult = [];
    for(let all of result){
      let ifBlock = content.slice(all.start,all.end);
      const expMatch = ifBlock.match(/^<if exp="(.*?)">/);
      let [block,expression,innerContent] = [ifBlock,expMatch ? expMatch[1] : null,ifBlock.replace(/^<if exp=".*?">/, '').replace(/<\/if>$/, '')];
      allResult.push({block,expression,innerContent})
    }
  // console.log(allResult);
    return allResult;

  }
  const getFor = (content)=>{
    let i = 0;
    let result = [];
    let opening = null;
    let openCount = 0;
    let closingCount = 0;
    while(i < (content.length - 1)){
      let phrase = content[i]+content[i+1]+content[i+2]+content[i+3]+content[i+4]+content[i+5];
      if(phrase == "<for e"){
      
      if(opening == null)opening = i;
      openCount++;
      };
      if(phrase == "</for>"){
      //console.log("here");
        closingCount++;
      if(openCount == closingCount){
          result.push({start:opening,end:i+6});
          opening = null;
      }
      };
    i++;
    }
    let allResult = [];
    for(let all of result){
      let ifBlock = content.slice(all.start,all.end);
        const expMatch = ifBlock.match(/^<for exp="(.*?)">/);
      let [block,expression,innerContent] = [ifBlock,expMatch ? expMatch[1] : null,ifBlock.replace(/^<for exp=".*?">/, '').replace(/<\/for>$/, '')];
      allResult.push({block,expression,innerContent})
    }
    return allResult;

  }
  const getVar = (content)=>{
      let c = content.matchAll(/<var>(.*?)<\/var>/g);
      let result = [];
      for(let i of c){
        let [block,innerContent] = i;
        result.push({block,innerContent});
      }
      return result;
  }
  const olEng = (content, variables = {}) => {
    if(!content)return '';
    let inlineVar = content.toString().matchAll(/\$(\w+)/g);
        for(let i of inlineVar){
      if(i[1] in variables){
         let useVariable;
        if(typeof variables[i[1]] == "object"){
            // console.log()
           useVariable = JSON.stringify(variables[i[1]]);
        }else{
          useVariable = variables[i[1]];
        }
      content = content.replaceAll(i[0],useVariable);
      }  
    }
    
    for (let i of getVar(content)){
      let ob = i.innerContent.split(".");
       let current = variables[i.innerContent];
      if(ob.length > 1){
        current = "";
          for(let i =1;i < ob.length;i++){
            current = variables[ob[i]]
          if(current)
          
           current = current[ob[i]];
          }
         
          
      }
      let Var = current;
      if (Var == undefined) console.warn(i.innerContent + " is undefined");
     content = content.replace(i.block,Var);
     if(/<if exp/.test(content)){
       content =  olEng(content, variables);
     }
    }
// for processor
    for (let i of getFor(content)) {
     // console.log(i.expression)
      let proccesed = processor(
         'for',
        i.expression,
        i.innerContent,
        variables
      );
      content = content.replace(i.block,proccesed);
       if(/<for exp/.test(content)){
       content =  olEng(content, variables);
     }
    }
// if processor
  for (let i of getIf(content)) {
      let proccesed = processor(
        'if',
        i.expression,
        i.innerContent,
        variables
      );
      content = content.replace(i.block,proccesed);
    }
    return content;
  }
  const processor = (tag,exp,body,variables)=>{
       let expParse = exp.match(/(.*?)\s*(>|<|<=|>=|==|!=|\(in\))\s*(.*)/);
         if(!expParse)throw 'Invalid expression around "'+exp.slice(0,10)+'"';
      let [_,left,oprand,right] = expParse;
     
      let regex = new RegExp(`\\$(.*?)$`);
      left = left.trim().toString();
      right = right.trim().toString();
     if(right[right.length -1]=="'" && right[0]=="'" || right[right.length -1]=='"' && right[0]=='"')right=right.slice(1,right.length-1)
     if(left[left.length -1]=="'" && left[0]=="'" || left[left.length -1]=='"' && left[0]=='"')left=left.slice(1,left.length-1)
     
      if (right.match(regex)) { 
           right = variables[right.match(regex)[1]];
        }
     if(tag == "if"){
         if (left.match(regex)) {
          left = variables[left.match(regex)[1]];
        }
     }

     let response = '';
      if(right == "true" || right == "false")right = Boolean(right);
      if(left == "true" || left == "false")left = Boolean(right);
       switch(oprand){
          case "==":
            
            response = (left == right)?body:response;
          break;
          case "!=":
            response = (left != right)?body:response;
          break;
          case ">=":
            response = (left >= right)?body:response;
          break;
          case "<=":
            response = (left <= right)?body:response;
          break;
           case ">":
            response = (left > right)?body:response;
          break;
           case "<":
            response = (left < right)?body:response;
          break;
          case "(in)":
            try{
              response = "";
               
              //if(right[0] != "{")right=`[\"${right.split(",").join('","')}\"]`;
              // = JSON.parse(right);
              //console.log(right)
               right = JSON.parse(right);
              
               for(let v in right){
                let compiled = body;
            const regex = new RegExp(`(\\${left})\\.?([\\w]+)?`, 'g');
                   
                 if(regex.test(body)){
                    
                   regex.lastIndex = 0;
                   let paths = body.matchAll(regex);
                   for(let i of paths){
                      let [__,placeholder,key] = i;
                     if(key == undefined){
                          compiled = compiled.replaceAll(placeholder,right[v]); 
                      }else{
                          compiled = compiled.replaceAll(__,right[v][key]); 
                      }
                     
                   }
                  
                 }
              
                   
                 response += compiled;     
             }
             }catch(e){
              console.error(e, `@ ${left} in ${right}`)
             }
          break;

       }
     return response;
  } 
export {ojs}

/* */